import{c as t,Q as a,j as s,m as o}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"A harness for every task: dynamic workflows in Claude Code","description":"","frontmatter":{"url":"https://x.com/trq212/status/2061907337154367865","title":"A harness for every task: dynamic workflows in Claude Code","author":"Thariq","archived":"2026-06-15T00:00:00.000Z","handle":"@trq212","published":"2026-06-02T00:00:00.000Z","score":"9.5/10","stats":"10,351 likes · 1,352 retweets","tags":["dynamic-workflows","harness","agent-orchestration","non-technical","best-practices","claude-code","subagents"],"type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-06-02-@trq212-367865.md","filePath":"research/tweets/2026-06-02-@trq212-367865.md","lastUpdated":1785909234000}'),r={name:"research/tweets/2026-06-02-@trq212-367865.md"};function n(i,e,l,d,h,c){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="a-harness-for-every-task-dynamic-workflows-in-claude-code-—-trq212" tabindex="-1">A harness for every task: dynamic workflows in Claude Code — @trq212 <a class="header-anchor" href="#a-harness-for-every-task-dynamic-workflows-in-claude-code-—-trq212" aria-label="Permalink to &quot;A harness for every task: dynamic workflows in Claude Code — @trq212&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/trq212/status/2061907337154367865" target="_blank" rel="noreferrer">https://x.com/trq212/status/2061907337154367865</a><strong>作者</strong>：Thariq（@trq212） <strong>發布日期</strong>：2026-06-02 <strong>收錄日期</strong>：2026-06-15 <strong>類型</strong>：Twitter Article（長文） <strong>統計</strong>：10,351 likes · 1,352 retweets</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>Claude Code&#39;s dynamic workflows are the biggest capability upgrade since Skills and Subagents shipped. After deep-diving them with @sidbid, here&#39;s what we found.</p><h3 id="what-is-a-dynamic-workflow" tabindex="-1">What Is a Dynamic Workflow? <a class="header-anchor" href="#what-is-a-dynamic-workflow" aria-label="Permalink to &quot;What Is a Dynamic Workflow?&quot;">​</a></h3><p>Unlike static agent systems where you predefine the orchestration, dynamic workflows let Claude <em>write the orchestration script on the fly</em> as a JavaScript file, then execute it.</p><p>The result:</p><ul><li>The harness itself becomes a deliverable (saveable, versionable, reusable)</li><li>100+ parallel agents without context window pollution</li><li>Routing logic is deterministic code, not probabilistic LLM turns</li></ul><h3 id="the-harness-paradigm-shift" tabindex="-1">The Harness Paradigm Shift <a class="header-anchor" href="#the-harness-paradigm-shift" aria-label="Permalink to &quot;The Harness Paradigm Shift&quot;">​</a></h3><p>Previous Claude Code architecture:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>You → Claude (orchestrator) → Subagents (workers)</span></span></code></pre></div><p>With Dynamic Workflows:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>You → Claude (workflow author) → JS Harness → Agents (workers)</span></span></code></pre></div><p>The crucial difference: routing and orchestration logic moved from LLM inference to deterministic code. Every conditional, every filter, every worker assignment is now inspectable JavaScript.</p><p>This means:</p><ol><li><strong>Reproducibility</strong>: Same workflow script = same behavior (unlike pure LLM orchestration)</li><li><strong>Auditability</strong>: You can read, modify, and understand the exact orchestration logic</li><li><strong>Composability</strong>: Workflows can call skills, which can call subagents</li><li><strong>Cost predictability</strong>: Routing doesn&#39;t burn tokens</li></ol><h3 id="when-to-use-each-tool" tabindex="-1">When to Use Each Tool <a class="header-anchor" href="#when-to-use-each-tool" aria-label="Permalink to &quot;When to Use Each Tool&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tool</th><th>Use When</th><th>Cost Profile</th></tr></thead><tbody><tr><td>Ask Claude</td><td>One-off question, single context</td><td>Low</td></tr><tr><td>Skill</td><td>Repeatable process, reusable recipe</td><td>Low</td></tr><tr><td>Subagent</td><td>Task needs own context window</td><td>Medium</td></tr><tr><td>Agent Team</td><td>Tasks need inter-agent communication</td><td>High</td></tr><tr><td>/goal</td><td>Iterative: loop until done=true</td><td>Variable</td></tr><tr><td>Workflow</td><td>Massively parallel, independent tasks</td><td>High (predictable)</td></tr></tbody></table><h3 id="non-technical-workflows-that-now-make-sense" tabindex="-1">Non-Technical Workflows That Now Make Sense <a class="header-anchor" href="#non-technical-workflows-that-now-make-sense" aria-label="Permalink to &quot;Non-Technical Workflows That Now Make Sense&quot;">​</a></h3><p>This is what I&#39;m most excited about.</p><p>Before workflows, Claude Code was primarily a coding tool. Now:</p><p><strong>Research synthesis</strong>: Spin up 30 agents, each deep-researching one subtopic, synthesize into one report. Research that would take days → hours.</p><p><strong>Document analysis</strong>: 200-page legal document → 200 agents each analyzing one page in parallel → structured summary in minutes.</p><p><strong>Competitive monitoring</strong>: 50 competitor websites → 50 agents gathering intel → synthesized battle card.</p><p><strong>Customer feedback pipeline</strong>: 500 support tickets → parallel categorization + sentiment → executive summary.</p><p>The pattern: anything that&#39;s currently &quot;let me read through these 100 things&quot; becomes &quot;let me run a workflow.&quot;</p><h3 id="cost-control-principles" tabindex="-1">Cost Control Principles <a class="header-anchor" href="#cost-control-principles" aria-label="Permalink to &quot;Cost Control Principles&quot;">​</a></h3><p>The cost lever is: worker model × worker count × context size per worker.</p><p>Best practice pattern (Haiku workers, Opus synthesizer):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Orchestrator: Fable 5 / Opus (writes the harness, synthesizes results)</span></span>
<span class="line"><span>Workers: Haiku (does the parallel work)</span></span></code></pre></div><p>This gives you:</p><ul><li>Intelligent orchestration (expensive model, single turn)</li><li>Cheap parallelism (Haiku × N workers)</li><li>Intelligent synthesis (expensive model, reads all results)</li></ul><p>Rule of thumb: if a task breaks into 10+ independent pieces, workflow + Haiku workers beats Opus doing it sequentially.</p><h3 id="workflow-anti-patterns" tabindex="-1">Workflow Anti-Patterns <a class="header-anchor" href="#workflow-anti-patterns" aria-label="Permalink to &quot;Workflow Anti-Patterns&quot;">​</a></h3><p>❌ <strong>Unbounded scope</strong>: &quot;Audit my entire computer&quot; → spawns infinite agents ❌ <strong>Expensive workers</strong>: All-Opus workflow = 100× cost vs Haiku workers<br> ❌ <strong>No synthesis step</strong>: Raw parallel results without a summarizer = information dump ❌ <strong>forgetting /workflows</strong>: Use <code>/workflows</code> to monitor live, pause, and stop runaway agents</p><h3 id="the-workflows-monitor" tabindex="-1">The /workflows Monitor <a class="header-anchor" href="#the-workflows-monitor" aria-label="Permalink to &quot;The /workflows Monitor&quot;">​</a></h3><p>While a workflow runs, <code>/workflows</code> shows:</p><ul><li>All active agents and their current task</li><li>Token usage per agent (real-time)</li><li>Tools being called</li><li>Time elapsed</li></ul><p>You can stop individual agents or the entire workflow from here. This is your kill switch.</p><h3 id="saving-and-reusing-workflows" tabindex="-1">Saving and Reusing Workflows <a class="header-anchor" href="#saving-and-reusing-workflows" aria-label="Permalink to &quot;Saving and Reusing Workflows&quot;">​</a></h3><p>Claude saves the JS file, but check <em>where</em> it saves.</p><p>Default: somewhere in the global Claude Code working directory (not your project).</p><p>Always tell Claude: &quot;Save the workflow script to <code>.claude/workflows/</code>&quot;</p><p>Then version it in git. A workflow is infrastructure. Treat it like code.</p><h3 id="nesting-workflows-inside-goal" tabindex="-1">Nesting: Workflows Inside /goal <a class="header-anchor" href="#nesting-workflows-inside-goal" aria-label="Permalink to &quot;Nesting: Workflows Inside /goal&quot;">​</a></h3><p>The most powerful (and dangerous) pattern:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/goal: keep improving product until user satisfaction &gt; 90%</span></span>
<span class="line"><span>  → runs a workflow each iteration</span></span>
<span class="line"><span>    → 50 agents analyze user feedback</span></span>
<span class="line"><span>    → synthesis agent updates product specs</span></span>
<span class="line"><span>    → main session implements changes</span></span>
<span class="line"><span>  → /goal checks satisfaction metric</span></span>
<span class="line"><span>  → loops until done=true</span></span></code></pre></div><p>This is autonomous product iteration. Set it up carefully. Set explicit stopping conditions. Monitor closely.</p><h3 id="bottom-line" tabindex="-1">Bottom Line <a class="header-anchor" href="#bottom-line" aria-label="Permalink to &quot;Bottom Line&quot;">​</a></h3><p>Dynamic workflows aren&#39;t a gimmick. They&#39;re a fundamental shift in what Claude Code can parallelize.</p><p>The question isn&#39;t &quot;should I use workflows?&quot; The question is: &quot;which of my current multi-hour tasks could become multi-minute workflows?&quot;</p><p>Start with something bounded. Audit a specific folder. Analyze a specific dataset. Get comfortable with the costs before going large.</p><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>10/10</td><td>成本公式、.claude/workflows/ 儲存、/workflows 監控、anti-patterns，全套可立即執行</td></tr><tr><td>B. 創新性 (20%)</td><td>9/10</td><td>Harness paradigm shift 架構圖，routing 從 LLM 移至 deterministic code 這洞見清晰有力</td></tr><tr><td>C. 證據品質 (20%)</td><td>9/10</td><td>架構對比圖、工具選擇表、代碼範例、具體反模式均有根據</td></tr><tr><td>D. 技術深度 (15%)</td><td>10/10</td><td>最完整技術覆蓋：架構圖、成本公式、anti-patterns、/goal 嵌套模式</td></tr><tr><td>E. 泛化性 (15%)</td><td>9/10</td><td>適用所有規模和類型的 Claude Code 用戶</td></tr><tr><td><strong>加權總分</strong></td><td><strong>9.5/10</strong></td><td>A×0.3+B×0.2+C×0.2+D×0.15+E×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：SKILL <strong>理由</strong>：本文是 dynamic-workflows SKILL 的最佳主要參考來源，架構圖和 anti-patterns 應直接採用。</p>`,57)])])}const g=t(r,[["render",n]]);export{u as __pageData,g as default};
